def select_review(paths, maximum):
    """Admit all eligible paths or skip; maximum=None means unlimited."""
    selected = list(paths)
    if maximum is not None and (type(maximum) is not int or maximum <= 0):
        raise ValueError("maximum must be a positive integer or None")
    if any(not isinstance(path, str) or not path for path in selected):
        raise ValueError("eligible paths must be nonempty strings")
    if len(set(selected)) != len(selected):
        raise ValueError("eligible paths must be unique")
    if maximum is not None and len(selected) > maximum:
        return {"status": "skipped", "selected": selected, "assigned": []}
    return {"status": "ready", "selected": selected, "assigned": selected}


def queue_review(paths, maximum, dispatch):
    plan = select_review(paths, maximum)
    if plan["status"] == "ready":
        for path in plan["assigned"]:
            dispatch(path)
    return plan
